SELECT 
FROM name_usage_archive
WHERE dataset_key=#{key.datasetKey} AND id=#{key.id}

mapper.update:
UPDATE name_usage_archive a
SET release_keys = t.keys
FROM (
  SELECT x.id, coalesce((SELECT array_agg(DISTINCT k ORDER BY k) FROM unnest(x.release_keys) AS k), '{}'::int[]) AS keys
  FROM name_usage_archive x
  WHERE x.dataset_key=#{projectKey}
) t
WHERE a.dataset_key=#{projectKey}
  AND a.id=t.id
  AND a.release_keys IS DISTINCT FROM t.keys

mapper.select:
SELECT EXISTS (
  SELECT true FROM name_usage_archive WHERE dataset_key=#{projectKey} AND release_keys @> ARRAY[${releaseKey}]
)

mapper.update:
UPDATE name_usage_archive a SET superseded_by = null
FROM name_usage u
WHERE a.dataset_key=#{projectKey}
  AND u.dataset_key=${releaseKey}
  AND a.id=u.id
  AND a.superseded_by IS NOT NULL

UPDATE name_usage_archive a SET superseded_by = s.superseded_by
FROM usage_id_superseded s
WHERE s.dataset_key=#{releaseKey}
  AND a.dataset_key=#{projectKey}
  AND a.id=s.id
  AND a.superseded_by IS DISTINCT FROM s.superseded_by

  AND NOT EXISTS (
    SELECT true FROM name_usage u
    WHERE u.dataset_key IN (${k}) AND u.id=s.id
  )
